		/** 
		 * Tests creating a new BIQuery.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a BIQuery");

			StringBuilder msg = new StringBuilder( "-- Failed to create a BIQuery" );

			try {            
				BIQuery entity = BIQueryService.getBIQueryInstance().createBIQuery( generateNewEntity() );
				thePrimaryKey = entity.getBIQueryId();
				LOGGER.info( "-- Successfully created a BIQuery with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a BIQuery. 
		 */
		public BIQuery testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created BIQuery" );

			BIQuery entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read BIQuery with primary key" );
			msg.append( thePrimaryKey );
			
			BIQueryFetchOneSummary fetchOneSummary = new BIQueryFetchOneSummary( thePrimaryKey );

			try {
				entity = BIQueryService.getBIQueryInstance().getBIQuery( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found BIQuery " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a BIQuery.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a BIQuery." );

			StringBuilder msg = new StringBuilder( "Failed to update a BIQuery : " );        
			BIQuery entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created BIQuery." );

				// for use later on...
				thePrimaryKey = entity.getBIQueryId();

				BIQueryService proxy = BIQueryService.getBIQueryInstance();            
				proxy.updateBIQuery( entity );   

				LOGGER.info( "-- Successfully saved BIQuery - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a BIQuery.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created BIQuery." );

			try{
			    BIQuery entity = testRead(); 
				BIQueryService.getBIQueryInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted BIQuery with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete BIQuery with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all BIQuerys.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of BIQuerys:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all BIQuery : " );        
			List<BIQuery> collection  = null;

			try {
				// call the static get method on the BIQueryService
				collection = BIQueryService.getBIQueryInstance().getAllBIQuery();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					BIQuery entity = null;            
					Iterator<BIQuery> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getBIQueryId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

